import numpy as np

class NeuralNetworkTopologyLandscape:
    """
    A highly multimodal optimization landscape inspired by neural network weight spaces.
    Creates irregular basin structures through layer-specific activation patterns and synaptic coupling.

    Key Features:
        - Layer-specific sigmoid activations with exponential decay
        - Synaptic coupling between dimensions creating complex interactions
        - Position-dependent amplitude modulation for basin size heterogeneity
        - Global minimum at origin with dense local minima networks

    Attributes:
        dim (int): Number of dimensions for the optimization problem.
    """

    def __init__(self, dim=10):
        self.dim = dim

        # Configuration constants
        self.layer_frequencies = np.linspace(1.5, 4.5, dim)
        self.synaptic_strength = 2.3
        self.decay_rate = 0.8
        self.coupling_density = 0.6

        # Initialize random parameters with fixed seed for reproducibility
        np.random.seed(123)

        # Layer-specific activation parameters
        self.layer_activations = np.random.uniform(0.5, 2.0, size=dim)
        self.synaptic_connections = []
        for i in range(dim):
            for j in range(i+1, dim):
                if np.random.rand() < self.coupling_density:
                    self.synaptic_connections.append([i, j])

    def _safe_array(self, x):
        """Convert input to numpy array with proper shape handling."""
        try:
            arr = np.asarray(x)
            return arr.astype(np.float64)
        except Exception:
            if hasattr(x, 'to_numpy'):
                return x.to_numpy().astype(np.float64)
            elif isinstance(x, (list, tuple)):
                return np.array(list(x), dtype=np.float64)
            else:
                return np.atleast_1d(float(x))

    def f(self, x):
        """
        Evaluates the NeuralNetworkTopologyLandscape objective function.

        Args:
            x (array-like): A real-valued sample or batch of samples in domain [-5, 5].

        Returns:
            float/array: The objective value(s) to minimize. Global minimum at origin = 0.
        """
        # Safe array conversion
        x_in = self._safe_array(x)
        original_shape = x_in.shape if len(x_in.shape) > 1 else (x_in.size,)

        is_scalar = np.isscalar(x_in) or (len(original_shape) == 0)

        if is_scalar:
            x_batched = np.array([float(x_in)], dtype=np.float64).reshape(1, -1)
            return_single = True
        elif len(x_in.shape) == 1:
            x_batched = x_in.reshape(-1).astype(np.float64).reshape((1, self.dim))
            return_single = True
        else:
            # Handle batch case with proper dimension checking
            if x_in.shape[-1] < self.dim:
                x_batched = np.pad(x_in.astype(np.float64), ((0,0),(0,self.dim-x_in.shape[-1])))
            elif x_in.shape[-1] > self.dim:
                x_batched = x_in[..., :self.dim].astype(np.float64)
            else:
                x_batched = x_in.astype(np.float64)
            return_single = False

        # Global quadratic term
        quadratic = np.sum(x_batched**2, axis=1)

        # Layer-specific sigmoid activations
        layer_activations = np.zeros_like(quadratic)
        for i in range(self.dim):
            activation = self.layer_activations[i] * (1 - 1/(1 + np.exp(-self.layer_frequencies[i] * x_batched[:,i])))
            layer_activations += 0.7 * activation * np.exp(-self.decay_rate * np.sum(x_batched**2, axis=1))

        # Synaptic coupling between dimensions
        synaptic_coupling = np.zeros_like(quadratic)
        for i, j in self.synaptic_connections:
            synapse = np.sin(self.layer_frequencies[i] * x_batched[:,i]) * np.cos(self.layer_frequencies[j] * x_batched[:,j])
            synaptic_coupling += 0.5 * synapse * (1 + 0.2 * np.tanh(x_batched[:,i] * x_batched[:,j]))

        # Position-dependent amplitude modulation
        amplitude_modulation = np.zeros_like(quadratic)
        for i in range(self.dim):
            amp_term = np.exp(-0.3 * np.abs(x_batched[:,i])) * (1 + 0.4 * np.sin(2 * x_batched[:,i]))
            amplitude_modulation += 0.6 * amp_term

        # Final combination
        result = quadratic + layer_activations + synaptic_coupling + amplitude_modulation

        if return_single:
            return float(result[0])
        else:
            return result.reshape(original_shape)
